import re
from html.parser import HTMLParser

# Read the page 32 content
with open('/app/resources/treasury_bulletin_1941_05_page_32.txt', 'r') as f:
    content = f.read()

# Parse HTML table 
class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.rows = []
        self.current_row = []
        self.current_data = []
        self.in_tr = False
        self.in_td = False

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.in_tr = True
            self.current_row = []
        elif tag == 'td' or tag == 'th':
            self.in_td = True
            self.current_data = []

    def handle_endtag(self, tag):
        if tag == 'td' or tag == 'th':
            if self.in_td:
                cell_text = ''.join(self.current_data).strip()
                self.current_row.append(cell_text)
                self.in_td = False
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
            self.in_tr = False

    def handle_data(self, data):
        if self.in_td:
            self.current_data.append(data)

parser = TableParser()
parser.feed(content)

# Get section boundaries
# A section is from a year header to (but not including) the next year header or end of table
# We look for year headers in the first column (columns 0-3)

def find_year_headers():
    year_headers = []  # list of (row_index, year)
    for i, row in enumerate(parser.rows):
        if len(row) >= 4:
            desc = row[0]
            if desc and desc.strip() and re.match(r'^\d{4}$', desc.strip()):
                year_headers.append((i, desc.strip()))
    return year_headers

year_headers = find_year_headers()
print("Year headers with their row indices:")
for idx, yr in year_headers:
    print(f"  Row {idx}: {yr}")

# For each row, find the most recent year header at or before it
def get_year_for_row(row_idx, year_headers):
    # Find the year that applies to this row
    # It's the last year header where header_row <= row_idx
    applicable_year = None
    for header_row, year in year_headers:
        if header_row <= row_idx:
            applicable_year = year
        else:
            break
    return applicable_year

# Find all Nat Defense items
print("\n\n=== Processing National Defense Series items ===")
results = []
for i, row in enumerate(parser.rows):
    if len(row) >= 4:
        desc = row[0]
        if 'Nat. Defense' in desc:
            fixed = row[1]
            callable_col = row[2]

            year = get_year_for_row(i, year_headers)

            # Clean values
            fixed_val = int(fixed.replace(',', '')) if fixed and fixed not in ['1%', '-', ''] else 0
            callable_val = int(callable_col.replace(',', '')) if callable_col and callable_col not in ['-', ''] else 0

            total = fixed_val + callable_val

            print(f"\nRow {i}: {desc}")
            print(f"  First callable year: {year}")
            print(f"  Fixed: {fixed_val}, Callable: {callable_val}, Total: {total}")

            results.append({
                'year': year,
                'description': desc,
                'fixed': fixed_val,
                'callable': callable_val,
                'total': total
            })

# Summarize by year
print("\n\n=== SUMMARY BY FIRST CALLABLE YEAR ===")
year_totals = {}
for r in results:
    yr = r['year']
    if yr not in year_totals:
        year_totals[yr] = 0
    year_totals[yr] += r['total']

for yr in sorted(year_totals.keys()):
    print(f"  {yr}: {year_totals[yr]} million")

print(f"\n=== GRAND TOTAL: {sum(year_totals.values())} million ===")
